import { type ClassValue, clsx } from "clsx"
import { twMerge } from "tailwind-merge"

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs))
}

export function formatNumber(val: number | null | undefined, decimals: number = 1): string {
  if (val === null || val === undefined || isNaN(val)) return "N/A"
  return val.toFixed(decimals)
}

export function getRiskColor(category: string): string {
  switch (category) {
    case 'CRITICAL_RISK':
      return '#EF4444' // Red
    case 'HIGH_RISK':
      return '#F97316' // Orange
    case 'MODERATE_RISK':
      return '#FBBF24' // Yellow
    case 'LOW_RISK':
      return '#10B981' // Green
    default:
      return '#38BDF8' // Blue
  }
}

export function getRiskBadgeClass(category: string): string {
  switch (category) {
    case 'CRITICAL_RISK':
      return 'bg-red-950/80 text-red-400 border-red-500/50'
    case 'HIGH_RISK':
      return 'bg-orange-950/80 text-orange-400 border-orange-500/50'
    case 'MODERATE_RISK':
      return 'bg-amber-950/80 text-amber-400 border-amber-500/50'
    case 'LOW_RISK':
      return 'bg-emerald-950/80 text-emerald-400 border-emerald-500/50'
    default:
      return 'bg-slate-900 text-slate-400 border-slate-700'
  }
}
